    private void artwork()throws Exception{String[] kinds={"computer","network","files","documents","pictures","music","videos","downloads","browser","notes","control","appearance","drive","search","pdffile","archivefile"};Bitmap sheet=Bitmap.createBitmap(720,680,Bitmap.Config.ARGB_8888);ui(()->{Canvas c=new Canvas(sheet);c.drawColor(0xffe8eef3);Paint label=new Paint(3);label.setColor(0xff263d50);label.setTextSize(16);label.setTextAlign(Paint.Align.CENTER);for(int i=0;i<kinds.length;i++){AeroIcon icon=new AeroIcon(home,kinds[i]);icon.layout(0,0,100,100);int save=c.save();c.translate(i%4*180+40,i/4*170+18);icon.draw(c);c.restoreToCount(save);c.drawText(kinds[i],i%4*180+90,i/4*170+142,label);}});try(FileOutputStream out=getTargetContext().openFileOutput("vista-icon-sheet.png",0)){sheet.compress(Bitmap.CompressFormat.PNG,100,out);}sheet.recycle();}
