    private List<DocumentFolders.Item> items(){AbsListView list=(AbsListView)find(explorer,v->"Folder contents".equals(v.getContentDescription()));List<DocumentFolders.Item> result=new ArrayList<>();if(list!=null)for(int i=0;i<list.getAdapter().getCount();i++){Object item=list.getAdapter().getItem(i);if(item instanceof DocumentFolders.Item)result.add((DocumentFolders.Item)item);}return result;}
    private View file(String name)throws Exception{awaitFile(name);return find(explorer,v->name.equals(v.getContentDescription()));}
    private void awaitFile(String name)throws Exception{await(()->{View item=find(explorer,v->name.equals(v.getContentDescription()));if(item!=null)return true;AbsListView list=(AbsListView)find(explorer,v->"Folder contents".equals(v.getContentDescription()));if(list!=null)for(int i=0;i<list.getAdapter().getCount();i++){Object value=list.getAdapter().getItem(i);if(value instanceof DocumentFolders.Item&&((DocumentFolders.Item)value).name.equals(name)){list.setSelection(i);break;}}return false;},"File is visible: "+name);}
    private Uri put(Uri parent,String name,byte[] data,String mime)throws Exception{Uri uri=DocumentsContract.createDocument(getTargetContext().getContentResolver(),parent,mime,name);try(OutputStream output=getTargetContext().getContentResolver().openOutputStream(uri,"w")){output.write(data);}return uri;}
    private Uri named(Uri folder,String name)throws Exception{for(DocumentOps.Ref item:DocumentOps.children(getTargetContext(),folder,new DocumentOps.Cancel()))if(item.item.name.equals(name))return item.uri;throw new FileNotFoundException(name);}
    private boolean exists(Uri folder,String name){try{named(folder,name);return true;}catch(Exception ex){return false;}}
    private boolean canRead(Uri uri){try{DocumentOps.stat(getTargetContext(),uri,new DocumentOps.Cancel());return true;}catch(Exception ex){return false;}}
    private DocumentOps.Ref reference(Uri uri,Uri parent)throws Exception{return new DocumentOps.Ref(uri,parent,DocumentOps.stat(getTargetContext(),uri,new DocumentOps.Cancel()));}
    private byte[] bytes(Uri uri)throws Exception{try(InputStream input=getTargetContext().getContentResolver().openInputStream(uri);ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1)output.write(buffer,0,n);return output.toByteArray();}}
    private String digest(byte[] bytes)throws Exception{StringBuilder out=new StringBuilder();for(byte value:MessageDigest.getInstance("SHA-256").digest(bytes))out.append(String.format(Locale.ROOT,"%02x",value&255));return out.toString();}
    private void close(String id)throws Exception{DesktopWindow window=window(id);if(window!=null){View close=find(window,v->"Close window".equals(v.getContentDescription()));if(close!=null)tap(close);}}
